package com.novacommerce.order.config; import java.time.Duration; import java.util.*; import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("order") public class OrderProperties {private final Auth auth=new Auth();private String catalogBaseUrl;private String inventoryBaseUrl;private Duration pendingCheckoutTimeout=Duration.ofMinutes(16);private Duration reconciliationInterval=Duration.ofSeconds(30);private List<String>allowedOrigins=List.of("http://localhost:3000");public Auth getAuth(){return auth;}public String getCatalogBaseUrl(){return catalogBaseUrl;}public void setCatalogBaseUrl(String v){catalogBaseUrl=v;}public String getInventoryBaseUrl(){return inventoryBaseUrl;}public void setInventoryBaseUrl(String v){inventoryBaseUrl=v;}public Duration getPendingCheckoutTimeout(){return pendingCheckoutTimeout;}public void setPendingCheckoutTimeout(Duration v){pendingCheckoutTimeout=v;}public Duration getReconciliationInterval(){return reconciliationInterval;}public void setReconciliationInterval(Duration v){reconciliationInterval=v;}public List<String>getAllowedOrigins(){return allowedOrigins;}public void setAllowedOrigins(List<String>v){allowedOrigins=v;}public static class Auth{private String issuer,audience,jwksUri;public String getIssuer(){return issuer;}public void setIssuer(String v){issuer=v;}public String getAudience(){return audience;}public void setAudience(String v){audience=v;}public String getJwksUri(){return jwksUri;}public void setJwksUri(String v){jwksUri=v;}}}
